INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerktopologien immer physisch sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch logische Topologien"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Netzwerktopologie für ein IT-System auswähle?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Bestimmt Wachstum"}, {"text": "Schnellste Installation", "correct": false, "because": "Struktur zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerktopologien gibt es?', 5, '[{"text": "Stern", "correct": true, "because": "Zentraler Knoten"}, {"text": "Bus", "correct": true, "because": "Ein Backbone"}, {"text": "Büro", "correct": false, "because": "Keine Topologie"}, {"text": "Farbtopologie", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Sterntopologie hat einen zentralen Knoten. b) Eine Ringtopologie ist immer langsamer als ein Stern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Netzwerktopologie für ein IT-System plane?', 4, '[{"text": "Verbindungspunkte", "correct": false, "because": "Bestimmen Struktur"}, {"text": "Fehlertoleranz", "correct": false, "because": "Sichert Betrieb"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerktopologien nur für große Netzwerke geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Netzwerktopologie?', 3, '[{"text": "Effiziente Kommunikation", "correct": true, "because": "Optimiert Datenfluss"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Struktur zählt"}, {"text": "Weniger Knoten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei Netzwerktopologien entscheidend?', 5, '[{"text": "Skalierbarkeit", "correct": true, "because": "Erlaubt Wachstum"}, {"text": "Fehlertoleranz", "correct": true, "because": "Sichert Betrieb"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Bustopologie nutzt ein zentrales Kabel. b) Eine Sterntopologie ist immer fehleranfälliger als ein Ring. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stern weniger fehleranfällig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Netzwerktopologie effektiv zu planen?', 4, '[{"text": "Knotenanzahl", "correct": false, "because": "Bestimmt Struktur"}, {"text": "Verbindungstyp", "correct": false, "because": "Beeinflusst Design"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Ringtopologie immer langsamer als eine Sterntopologie?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Design"}, {"text": "Ja", "correct": false, "because": "Zu vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Netzwerktopologien?', 4, '[{"text": "Effiziente Datenübertragung", "correct": true, "because": "Optimiert Kommunikation"}, {"text": "Fehlerisolierung", "correct": true, "because": "Erleichtert Diagnose"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerktopologien nur für kabelgebundene Netzwerke gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch drahtlos"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um eine Netzwerktopologie für ein IT-System auszuwählen?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Struktur"}, {"text": "Günstigste Lösung", "correct": false, "because": "Funktion wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Sterntopologie hat einen zentralen Knoten. b) Eine Bustopologie ist immer fehlertolerant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bus weniger fehlertolerant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Netzwerktopologien?', 5, '[{"text": "Knotenanordnung", "correct": true, "because": "Definiert Struktur"}, {"text": "Bandbreite", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Netzwerktopologie plane?', 3, '[{"text": "Fehlertoleranz", "correct": false, "because": "Sichert Betrieb"}, {"text": "Verbindungstyp", "correct": false, "because": "Bestimmt Design"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Sterntopologie immer fehleranfälliger als eine Ringtopologie?', 3, '[{"text": "Nein", "correct": true, "because": "Stern oft robuster"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerktopologien nur für große Netzwerke geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Netzwerktopologien?', 4, '[{"text": "Knotenanordnung", "correct": true, "because": "Definiert Struktur"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Struktur zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
